	@Override
	public boolean attackEntityAsMob(Entity entity) { 
		boolean hasHit = entity.attackEntityFrom(DamageSource.causeMobDamage(this), (float) ((int) getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue()));
		if (hasHit)
			applyEnchantments(this, entity);
		return hasHit;
	}

	@Override
	public boolean attackEntityFrom(DamageSource source, float damage) {
		if(this.isRiding() && (source.equals(DamageSource.IN_WALL) || source.equals(DamageSource.DROWN))) {
			return false;
		}
		if(source.getTrueSource() == this) {
			return false;
		}
		if(source.getImmediateSource() instanceof EntityBLArrow && (((EntityBLArrow) source.getImmediateSource()).getArrowType() == EnumArrowType.CHIROMAW_BARB || this.getElectricBoogaloo() && ((EntityBLArrow) source.getImmediateSource()).getArrowType() == EnumArrowType.CHIROMAW_SHOCK_BARB)) {
			return false;
		}
		if(this.getRidingEntity() != null && source.getTrueSource() == this.getRidingEntity() && !this.canRiderInteract()) {
			return false;
		}
		if(super.attackEntityFrom(source, damage)) {
			if(this.isSitting()) {
				this.setSitting(false);
			}
			return true;
		}
		return false;
	}

